const { c } = require("tar");
var {TypeDB, SessionType, TransactionType} = require("typedb-client")
var apiUtils = require("../util");

var fs  = require("fs")
var path = require("path")


var host= ""
var database= ""
var client = ""
var session = ""
var transaction = ""

// H O S T
// set server name
function set_host(req, res){
    var opts = {
        user: req.user,
        host: req.params[0],
        req: apiUtils.getRequestLogObject(req)
    }
    // console.log("Setting typedb host as : ", req.body.server)
    host = req.body.server;
    create_client(host).then(async function (client)
    {
        let database_list = await client.databases.all();
        let db_names = []
        for (const db in database_list){
            db_names.push(database_list[db]["_name"])
        }
        res.send(db_names);
    }).catch(function(err){
        apiUtils.rejectHandler(req, res, err);
    })
}
function get_host(req, res){
    res.send(host);
    return
}



// C L I E N T
async function create_client(host){
    client = await TypeDB.coreClient(host);
    return client
    // notify node-red of client exception
}
async function close_client(){
    await client.close();
    return
}
function get_client(){
    return client;
}
// D A T A B A S E
// list of all database
async function list_databases(req,res){
    try{
        let dbs = []
        let databases = await client.databases.all()
        for (const index in databases){
            dbs.push(databases[index]["_name"])
        }
       res.send(dbs); 
       return 
    }catch(exception){
        return exception
    }
}
// connect to a database 
async function set_database(db){
    try
    {
        console.log("Setting database to : ", db)
        database = db
        return
    }catch(exception){
        console.log(exception)
        return exception
    }
}
//create database
async function create_datatbase(){
    console.log("Creating database: ", database)
    await client.databases.create(database)
}
//delete a database
async function delete_database(){
    console.log("Deleting database: ", database)
    await(await client.databases.get(database)).delete();
}



//S E S S I O N S
async function create_session(session_type){
    try{
        console.log("Creating session to ", database, " of type  ", session_type);
        if(session_type === "DATA"){
            session = await client.session(database,SessionType.DATA);
        }else if(session_type === "SCHEMA"){
            session = await client.session(database,SessionType.SCHEMA);
        }
        return
    }catch(exception){
        console.log(exception);
        return exception
    }
}
async function close_session(){
    await session.close();
}
// T R A N S A C T I O N S
async function create_transaction(transaction_type){
    try{
        console.log("Creating transaction to ", database, " of type  ", transaction_type);
        if(transaction_type === "READ"){
            transaction = await session.transaction(TransactionType.READ);
        }else if(transaction_type === "WRITE"){
            transaction = await session.transaction(TransactionType.WRITE);
        }
    }catch(exception){
        // console.log(exception);
        return exception;
    }
}

async function close_transaction(transaction_type){
    try{    
        if(transaction_type === "READ"){
            transaction.close();
        }else if(transaction_type === "WRITE"){
            await transaction.commit();
        }
        return;
    }catch(exception){
        // console.log(exception);
        return;
    }
}


// K N O W L E D G E
async function knowledge(req, res){
    try{
        opts = req.body;
        set_database(opts.database);
        await create_session(opts.session_type);
        await create_transaction(opts.transaction_type);

        // if new schema and writing
        if(opts.session_type=== "SCHEMA" && opts.transaction_type === "WRITE" ){
            try{
                await transaction.query.define(opts.statement);
                await close_transaction();
                session.close()
                res.send("Successfully added schema to database " + database)
            }catch(exception){
                await close_transaction();
                session.close();
                throw exception
            }

        }
        // if reading schema
    }catch(exception){
        res.status(500).send(exception.message)
    }
}


// C A U S A L

async function causal_insert(opts , res){

    const promise = new Promise (function(resolve,reject){
        fs.readFile("./packages/node_modules/@node-red/editor-api/lib/admin/meta_model_schema.tql" ,"utf-8", async function (err,data,res){
            if(err) reject(err)
            // console.log("data ", data)
            // console.log("defining causal model schema ")
            try{
                await create_session("SCHEMA");
                await create_transaction("WRITE");
                try{
                    await transaction.query.define(data);
                }catch(exception){
                    console.log("caught exception a");
                    throw exception
                }
                await close_transaction("WRITE");
                await session.close();

            // causal models will establish sessions of type DATA
            
                if(opts.session_type=== "DATA" && opts.transaction_type === "WRITE" ){
                    // console.log("Writing causal instances to database : ", database)
                    // parse schema_statement into insert and match statements
                    await create_session(opts.session_type);
                    await create_transaction(opts.transaction_type);
                    await insert_iteratively(opts.statement);
                    await close_transaction(opts.transaction_type)
                    await session.close();
                    resolve("Added new causal model instance to database");
                }
            }catch(exception){
                console.log("caught exception b ")
                reject(exception)
            }
        })
    })
    promise.then(value => { res.send(value)}).catch(err =>{ res.status(500).send(err.message)})
}

// parse statement provided by typeql generator
async function insert_iteratively(insert_statement){
    console.log("inserting parsed statements iteratively ")
    let statements = insert_statement.split("~")
    for ( const index in statements){
        if(statements[index].length > 0){
            let statement = statements[index]
            if (statement[0] != "#" && statement[0] != "\n"){
                // transaction responsible for defining schema into database via  query manager
                // console.log("inserting:\n", statement);
                transaction.query.insert(statement);
            }
        } 
    }
}

async function causal(req, res){
    try{
        opts = req.body;

        if( await client.databases.contains(opts.database) ){
            set_database(opts.database);
            await delete_database();
            await create_datatbase();
            await causal_insert(opts,res)
        }

    }catch(exception){
        res.status(500).send(exception.message)
    }
}

module.exports ={
    // h o s t
    set_host: set_host,
    get_host: get_host,
    
    // c l i e n t
    close_client: close_client,
    get_client: get_client, 

    // d a t a b a s e
    get_all_databases : list_databases,
    set_database : set_database,
    
    // s e s s i o n s 
    create_session : create_session,
    
    // t r a n s a c t i o n s
    create_transaction: create_transaction,
    closes_transaction : close_transaction, 

    // d e p l o y
    knowledge: knowledge,
    causal: causal,
}

